],["arg7"]=[[jindaotext9;assqi2]],["id"]=[[rlt_asspanyan3]]},["rlt_assqi1"]={["arg1"]=[[玩家扣血]],["arg2"]=500,["arg3"]=[[烧]],["id"]=[[rlt_assqi1]]},["rlt_assqi2"]={["arg1"]=[[玩家扣血]],["arg2"]=200,["arg3"]=[[摔]],["id"]=[[rlt_assqi2]]},["rlt_assraddnpc1"]={["arg1"]=[[随机人物投放]],["id"]=[[rlt_assraddnpc1]]},["rlt_assraddnpc2"]={["arg1"]=[[随机人物投放]],["arg2"]=[[atr93_1;atr94_1;atr95_1;atr97_1;atr98_1]],["arg3"]=[[fb25_93;fb25_94;fb25_95;fb25_97;fb25_98]],["id"]=[[rlt_assraddnpc2]]},["rlt_assraddnpc3"]={["arg1"]=[[随机人物投放]],["arg2"]=[[assitem145,assitem160,assitem161,assitem162;assitem145,assitem160,assitem161,assitem151;assitem145,assitem154,assitem160,assitem161;assitem155,assitem145,assitem160,assitem161;assitem145,assitem160,assitem161,assitem162;assitem145,assitem160,assitem161,assitem162;assitem145,assitem160,assitem161,assitem157;assitem145,assitem160,assitem161,assitem156]],["arg3"]=[[fb25_169;fb25_170;fb25_171;fb25_172;fb25_174;fb25_175;fb25_176;fb25_177]],["id"]=[[rlt_assraddnpc3]]},["rlt_assstory1"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL莫少衡：玄门五绝曾师从长春观太虚真人，太虚真人乃是十多年前名震江湖的武林泰斗。传当年玄门道人曾于泰山论道，天下道人齐聚于此，文斗武斗，足足决了三天才决出文武前五甲。而这长春观太虚真人，却是论道武艺样样不输于人，在泰山论道中夺得魁首。;YEL莫少衡：然而正是这位真人，却收了数位败类为弟子，这五人原称长春五子，尽得太虚真人真传，却无善类，在江湖上声名狼藉，被太虚真人逐出师门。这五人脱离师门，更加猖獗起来，太虚真人气得卧病在床，没两年便去世了。;YEL莫少衡：而长春五子脱离师门之后，把师父所传玄门武学五行阵法练到极致，又因其心狠手辣，才得了“玄门五绝”的称号。;YEL莫少衡：少侠若是遇见这五个贼人，千万要小心他们的HIC五行阵法NOR。]],["arg3"]=[[3;3;3]],["id"]=[[rlt_assstory1]]},["rlt_asssuiji1"]={["arg1"]=[[随机结果]],["arg2"]=[[assjieguo1;assjieguo2;assjieguo4]],["arg3"]=[[1;1;1]],["id"]=[[rlt_asssuiji1]]},["rlt_asssuiji2"]={["arg1"]=[[随机结果]],["arg2"]=[[assjieguo5;assjieguo6]],["arg3"]=[[4;1]],["id"]=[[rlt_asssuiji2]]},["rlt_asssuiji3"]={["arg1"]=[[随机结果]],["arg2"]=[[assjieguo7;assjieguo8]],["arg3"]=[[5;1]],["id"]=[[rlt_asssuiji3]]},["rlt_asstankuang1"]={["arg1"]=[[弹出选项框]],["arg2"]=[[YEL莫少衡：少侠可是凌统领差来的？我是捕风卫的探子，已经调查玄门五绝多时。少侠可想知道他们的背景？]],["arg3"]=[[听]],["arg4"]=[[不听]],["arg5"]=[[assstory1;asschange16]],["arg6"]=[[asstext34]],["id"]=[[rlt_asstankuang1]]},["rlt_asstankuang2"]={["arg1"]=[[弹出选项框]],["arg2"]=[[YEL凌云：大慈恩寺如今失窃，根据我官府密报，乃是数伙江湖之人所为。阁下若是是能帮我夺回失窃之物，我自有重谢。]],["arg3"]=[[接受]],["arg4"]=[[拒绝]],["arg5"]=[[assmapbj11;asssuiji1;delete;asstext63]],["arg6"]=[[asstext64]],["id"]=[[rlt_asstankuang2]]},["rlt_asstext1"]={["arg1"]=[[文本输出]],["arg2"]=[[金平子嘴角溢血，单手护胸，自知不敌于你只得遁走逃离，仓惶间，所偷之物从怀中掉落。]],["id"]=[[rlt_asstext1]]},["rlt_asstext10"]={["arg1"]=[[文本输出]],["arg2"]=[[你步步紧逼，重伤了土御子，土御子嘴角溢血，脚步踉跄，只得逃跑，在逃跑之时五行阵法中众人似乎发生了变化。]],["id"]=[[rlt_asstext10]]},["rlt_asstext100"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你进入这里，发现地道内有一个深深的鞋印，似乎是刚刚有人走过。]],["id"]=[[rlt_asstext100]]},["rlt_asstext101"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你进入这里，发现地上有一丝白发，应该是刚刚走过的人留下的。]],["id"]=[[rlt_asstext101]]},["rlt_asstext102"]={["arg1"]=[[文本输出]],["arg2"]=[[你钻入了树洞，发现里面竟是一条机关道。]],["id"]=[[rlt_asstext102]]},["rlt_asstext103"]={["arg1"]=[[文本输出]],["arg2"]=[[你费了一番功夫方才钻入了树洞，但因为你进来的动作太大，脆弱的树干轰然倒塌，入口被封死了！你仔细观察周围，发现这里竟是一条地道，前方黑漆漆地不知道通往哪里。]],["id"]=[[rlt_asstext103]]},["rlt_asstext104"]={["arg1"]=[[文本输出]],["arg2"]=[[你将这乱石堆从原来的地方移了开来，发现刚刚石堆给你的奇异之感消失了。]],["id"]=[[rlt_asstext104]]},["rlt_asstext105"]={["arg1"]=[[文本输出]],["arg2"]=[[你走进了这条道路，发现里面竟是一座石林，你走了许久也未能走出去，你查看周围，一堆堆石块摆放得十分奇怪，似乎有些玄妙。]],["id"]=[[rlt_asstext105]]},["rlt_asstext106"]={["arg1"]=[[文本输出]],["arg2"]=[[你正准备挪开这石堆，却没想到“轰”地一声，有什么东西从石堆内爆裂，石子四散飞溅，你连忙闪避，可惜爆炸威力太大，你还是被石子给打伤了。]],["id"]=[[rlt_asstext106]]},["rlt_asstext107"]={["arg1"]=[[文本输出]],["arg2"]=[[你准备挪开这石堆，却没想到，这里面溅出一道绿水，你闪躲不及，被其击中，你中毒了！]],["id"]=[[rlt_asstext107]]},["rlt_asstext108"]={["arg1"]=[[文本输出]],["arg2"]=[[你准备挪开着石堆，这石堆之中，居然射出几道金光！]],["id"]=[[rlt_asstext108]]},["rlt_asstext109"]={["arg1"]=[[文本输出]],["arg2"]=[[你准备挪开着石堆，这石堆之中，居然是一个木制机关，从中射出一只飞箭！]],["id"]=[[rlt_asstext109]]},["rlt_asstext11"]={["arg1"]=[[文本输出]],["arg2"]=[[你紧追白发老者，眼看伸手便能擒住白发老者，哪知道白发老者伸脚在路边石块一踩，只听咔咔的机轴之声，不知道又触动了什么机关。]],["id"]=[[rlt_asstext11]]},["rlt_asstext110"]={["arg1"]=[[文本输出]],["arg2"]=[[你准备挪开着石堆，突然地面下陷，你一个不慎已是掉了下去！]],["id"]=[[rlt_asstext110]]},["rlt_asstext111"]={["arg1"]=[[文本输出]],["arg2"]=[[你之前中的毒被你用内力逼除，你恢复了正常。]],["id"]=[[rlt_asstext111]]},["rlt_asstext112"]={["arg1"]=[[文本输出]],["arg2"]=[[你挪开这座石堆，发现周围的迷雾渐渐都消散了，一条小路出现在你面前。]],["id"]=[[rlt_asstext112]]},["rlt_asstext113"]={["arg1"]=[[文本输出]],["arg2"]=[[你将石堆挪开，发现石堆之中竟然藏着一枚金元宝，你赶忙上去将其捡了起来！]],["id"]=[[rlt_asstext113]]},["rlt_asstext114"]={["arg1"]=[[文本输出]],["arg2"]=[[你将石堆挪开，发现这石堆之中插着一把荆木剑，你上去将其拾了起来。]],["id"]=[[rlt_asstext114]]},["rlt_asstext115"]={["arg1"]=[[文本输出]],["arg2"]=[[你将石堆挪开，发现这石堆之中竟然藏着一块真火玉佩！]],["id"]=[[rlt_asstext115]]},["rlt_asstext116"]={["arg1"]=[[文本输出]],["arg2"]=[[你将石堆挪开，发现这石堆之中竟然藏着一瓶稀灵水，此物可活血化瘀，乃是疗伤极品，也不知何人将其放在这里。]],["id"]=[[rlt_asstext116]]},["rlt_asstext117"]={["arg1"]=[[文本输出]],["arg2"]=[[你将石堆挪开，发现这石堆之中有一捧黄色泥土，十分奇怪。]],["id"]=[[rlt_asstext117]]},["rlt_asstext118"]={["arg1"]=[[文本输出]],["arg2"]=[[你使劲浑身解数，方才从这深坑中逃了出来。]],["id"]=[[rlt_asstext118]]},["rlt_asstext119"]={["arg1"]=[[文本输出]],["arg2"]=[[你掉入坑底，被摔了个半死，费了老大劲才从坑里爬了出来。]],["id"]=[[rlt_asstext119]]},["rlt_asstext12"]={["arg1"]=[[文本输出]],["arg2"]=[[你行至此处，贼人却不见了身影，却见旁边一人鬼鬼祟祟地，不如上前一问。]],["id"]=[[rlt_asstext12]]},["rlt_asstext120"]={["arg1"]=[[文本输出]],["arg2"]=[[你将柳春道处理后，仔细观察周围痕迹，发现脚印一直往东北方延伸，看来玄门五绝应是往此处逃走了。]],["id"]=[[rlt_asstext120]]},["rlt_asstext121"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL罗大龙：哼！我本不欲与阁下相争，阁下为何苦苦相逼！
