g1"]=[[弹出选项框]],["arg2"]=[[YEL凌风：我这边有几件棘手的事情，不知道你是否有时间帮我解决一下。]],["arg3"]=[[帮忙]],["arg4"]=[[不要]],["arg5"]=[[rybrsuiji1]],["arg6"]=[[rybrtext1]],["id"]=[[rlt_rybrtankuang1]]},["rlt_rybrtext1"]={["arg1"]=[[文本输出]],["arg2"]=[[你不想与官府有太多瓜葛，于是拒绝了凌风的请求。]],["id"]=[[rlt_rybrtext1]]},["rlt_rybrtext10"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：你陪我聊了那么久，我看也是口渴，这是宫中赏赐的贡茶金骏眉，你拿去喝吧。]],["id"]=[[rlt_rybrtext10]]},["rlt_rybrtext11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：我从凌捕头那顺了点好茶，你尝尝。可别告诉他啊！]],["id"]=[[rlt_rybrtext11]]},["rlt_rybrtext12"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：凌大人两兄弟都是十分厉害的人物，只是凌风大人隶属于崇武卫，凌云大人隶属于捕风卫。]],["id"]=[[rlt_rybrtext12]]},["rlt_rybrtext13"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：凌云大人已叫我暗中调查重光多日，我有什么发现都会第一时间告诉你。]],["id"]=[[rlt_rybrtext13]]},["rlt_rybrtext14"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：最近宫中来了一名名叫劳伦斯的皇商，我在想是不是和收纳异邦人的重光有什么联系。]],["id"]=[[rlt_rybrtext14]]},["rlt_rybrtext15"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：重光教最早是汉人建立的，可为什么会有那么多异邦人在其中呢？]],["id"]=[[rlt_rybrtext15]]},["rlt_rybrtext16"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：听说最近有一家生意红火的赌城，既然能称之为城，想必规模必然不小。]],["id"]=[[rlt_rybrtext16]]},["rlt_rybrtext17"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：重光教到底是哪来的财力能在各处修建规模庞大的分舵呢？]],["id"]=[[rlt_rybrtext17]]},["rlt_rybrtext18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：重光教选弟子的方式古怪，我们的人难以混进去。]],["id"]=[[rlt_rybrtext18]]},["rlt_rybrtext19"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：最近各地衙门都上报了凶杀案，最奇怪的是杀人者与被杀者并无任何关系，毫无动机。在调查清楚之前，你也要小心才好。]],["id"]=[[rlt_rybrtext19]]},["rlt_rybrtext2"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：捕风卫发现近日有重光教众频繁出没逍遥林，想必那里藏有他们的据点。若有人能找到，将获得朝廷重赏。]],["id"]=[[rlt_rybrtext2]]},["rlt_rybrtext20"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：偷偷给你说，我觉得凌风大人做事有些冲动，不如凌云大人稳重。]],["id"]=[[rlt_rybrtext20]]},["rlt_rybrtext21"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：听说重光弟子待遇十分好，想我堂堂官府，每月奉银也只能紧巴巴度日…咳，我并不是在对上面表示不满，你可别误会。]],["id"]=[[rlt_rybrtext21]]},["rlt_rybrtext22"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：除了江湖中大的门派势力，一些名不见经传的小门派似乎都依附了重光。]],["id"]=[[rlt_rybrtext22]]},["rlt_rybrtext23"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘青：听说重光总教之上藏着无数宝藏，富可敌国，我倒是想亲眼见见。]],["id"]=[[rlt_rybrtext23]]},["rlt_rybrtext24"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：这次辛苦少侠你了。]],["id"]=[[rlt_rybrtext24]]},["rlt_rybrtext25"]={["arg1"]=[[文本输出]],["id"]=[[rlt_rybrtext25]]},["rlt_rybrtext26"]={["arg1"]=[[文本输出]],["id"]=[[rlt_rybrtext26]]},["rlt_rybrtext27"]={["arg1"]=[[文本输出]],["id"]=[[rlt_rybrtext27]]},["rlt_rybrtext28"]={["arg1"]=[[文本输出]],["id"]=[[rlt_rybrtext28]]},["rlt_rybrtext29"]={["arg1"]=[[文本输出]],["id"]=[[rlt_rybrtext29]]},["rlt_rybrtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：捕风卫在嵩山发现了重光教的踪迹，那里应该有他们的分舵。你若是能捣毁他们，朝廷将重重有赏。]],["id"]=[[rlt_rybrtext3]]},["rlt_rybrtext4"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：太行谷已探明一处重光教据点，只是这个分舵隐藏在迷雾林之中，那里常年大雾弥漫，很容易迷失其中，派去的人都无功而返。若是你能找到，我会奖励你的。]],["id"]=[[rlt_rybrtext4]]},["rlt_rybrtext5"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：捕风卫来报，落英谷有重光教众的踪迹。若有能捣毁者，将获得重赏。]],["id"]=[[rlt_rybrtext5]]},["rlt_rybrtext6"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：据你的描述，那人是罗刹国的波洛罗夫，曾是一名死囚，独自杀死数十名看守逃脱。此人力大无穷，性格暴戾，你能活着回来，真是了不起。]],["id"]=[[rlt_rybrtext6]]},["rlt_rybrtext7"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：以杀人来洗脱人的罪孽，这种人既疯狂又可怜。]],["id"]=[[rlt_rybrtext7]]},["rlt_rybrtext8"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：听你一说，她倒不像个坏人。只是人心叵测，你也不要太过相信她的话便是。]],["id"]=[[rlt_rybrtext8]]},["rlt_rybrtext9"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：依你所言他收留乞丐，也不知道是因为真的心善还是另有所图。]],["id"]=[[rlt_rybrtext9]]},["rlt_rybrtimebj1"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[每日波洛罗夫]],["arg3"]=1,["id"]=[[rlt_rybrtimebj1]]},["rlt_rybrtimebj2"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[每日什纳罗]],["arg3"]=1,["id"]=[[rlt_rybrtimebj2]]},["rlt_rybrtimebj3"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[每日卡米尔]],["arg3"]=1,["id"]=[[rlt_rybrtimebj3]]},["rlt_rybrtimebj4"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[每日库利亚]],["arg3"]=1,["id"]=[[rlt_rybrtimebj4]]},["rlt_rybrtimebj5"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[完成每日任务]],["arg3"]=1,["id"]=[[rlt_rybrtimebj5]]},["rlt_rybrtimebj6"]={["arg1"]=[[玩家时间标记变化]],["arg2"]=[[获得茶叶]],["arg3"]=1,["id"]=[[rlt_rybrtimebj6]]},["rlt_sanrenliangong1"]={["arg1"]=[[换